import{_ as i,c as a,o as s,ak as t,ao as r}from"./chunks/framework.DWj_FwGv.js";const f=JSON.parse('{"title":"Service","description":"PURISTA typescript framework service creation","frontmatter":{"title":"Service","description":"PURISTA typescript framework service creation","order":201000},"headers":[],"relativePath":"handbook/2_building_business-logic/service/index.md","filePath":"handbook/2_building_business-logic/service/index.md","lastUpdated":1770406425000}'),n={name:"handbook/2_building_business-logic/service/index.md"};function o(c,e,l,d,h,m){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="service" tabindex="-1">Service <a class="header-anchor" href="#service" aria-label="Permalink to “Service”">​</a></h1><p><img src="'+r+'" alt="Add service with cli"></p><p>A service is a logical group of functions and subscriptions. This is where the domain-driven aspect comes in.</p><p>A service provides:</p><ul><li><a href="./../command/">Commands</a> that are callable by the outside world (like an API).</li><li><a href="./../subscription/">Subscriptions</a> that listen to events and react accordingly.</li><li>A custom <a href="./add-a-service-config.html">service configuration</a>, which is available in commands and subscriptions.</li><li><a href="./../stores/secret-stores.html">Secret stores</a>, which allow commands and subscriptions to access secrets via a unified interface.</li><li><a href="./../stores/config-stores.html">Config stores</a>, which allow commands and subscriptions to access (dynamic) configurations via a unified interface.</li><li><a href="./../stores/state-stores.html">State stores</a>, which allow commands and subscriptions to access state data via a unified interface.</li><li><a href="./define-resources.html">Resources</a>, which are used by commands and subscriptions (e.g., database connections or external APIs).</li></ul><p>In general, a service itself should not contain any logic. It should only act as a logical container for commands and subscriptions.<br> Additionally, services should not hold state data.</p><h2 id="typical-implementation-order" tabindex="-1">Typical implementation order <a class="header-anchor" href="#typical-implementation-order" aria-label="Permalink to “Typical implementation order”">​</a></h2><ol><li>Define service info and create service builder.</li><li>Add config schema (if needed).</li><li>Define resources used by commands/subscriptions.</li><li>Add command and subscription definitions.</li><li>Create service instance, provide required resources (<code>getInstance(..., { resources })</code>), and call <code>start()</code>.</li></ol><p>Continue with:</p><ul><li><a href="./the-service-builder.html">The service builder</a></li><li><a href="./add-a-service-config.html">Add configuration</a></li><li><a href="./define-resources.html">Define resources</a></li><li><a href="./unit-test-a-service.html">Unit test the service</a></li></ul><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to use”">​</a></h2><ul><li>You want to group related commands/subscriptions by domain.</li><li>You need shared resources/config for a set of functions.</li><li>You want clear boundaries for ownership and deployment.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to “Common pitfalls”">​</a></h2><ul><li>putting business logic into the service class itself</li><li>mixing unrelated domains into one service</li><li>storing mutable runtime state directly on the service instance</li></ul><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to “Checklist”">​</a></h2><ul><li>service info is stable and meaningful (<code>serviceName</code>, <code>serviceVersion</code>)</li><li>config schema is defined where needed</li><li>resources are typed and passed at instance creation</li><li>service setup test (<code>testServiceSetup</code>) is present</li></ul><h2 id="idea-behind-the-design" tabindex="-1">Idea Behind the Design <a class="header-anchor" href="#idea-behind-the-design" aria-label="Permalink to “Idea Behind the Design”">​</a></h2><p>When a new service is added, it is done via the service builder. The service builder is responsible for collecting all required information. It then provides clearly defined interfaces. By having these interfaces, the actual implementation of a resource, store, or any other dependency can be easily swapped out without affecting other parts of the system.</p><p>With the ability to simply swap out dependencies, vendor lock-in can be significantly reduced. For example, if you move your system from one cloud provider to another, you only need to update the adapter for the secret store or config store—without modifying any of your business logic.</p><p>The combination of well-defined interfaces and a message-based architecture makes integrating other systems seamless. It does not matter how these systems are built internally; all that matters is that they provide the correct interfaces. This allows for a combination of different programming languages, the integration of third-party services, and more.</p><p><strong>See</strong>: <a href="./../connect_to_a_purista_application/export_service_definitions.html">Export Service Definitions</a></p>',21)])])}const p=i(n,[["render",o]]);export{f as __pageData,p as default};
